export function surfaceArt(key){return `<svg viewBox="0 0 300 110" aria-hidden="true" class="surface-art">${finishingDefs()}<defs><clipPath id="surface-clip"><rect x="4" y="4" width="292" height="102" rx="6"/></clipPath></defs><g clip-path="url(#surface-clip)"><rect width="300" height="110" fill="url(#f-metal)"/>${Array.from({length:24},(_,i)=>`<path d="M0 ${4+i*4.3}L300 ${i*4.3-3}" stroke="${i%2?'#e7f9f6':'#415b66'}" opacity=".18" stroke-width=".6"/>`).join('')}<g data-surface-rust opacity="0" filter="url(#f-grain)">${rustPatches()}</g>${key==='oil'?'<rect width="300" height="110" fill="url(#f-oil)"/><path d="M12 15Q150 40 289 10M12 82Q140 112 289 83" fill="none" stroke="#fff3c8" opacity=".6" stroke-width="2"/>':''}</g><rect x="4" y="4" width="292" height="102" rx="6" fill="none" stroke="#b2c5c2" stroke-width="2"/></svg>`;}
